						client,
						serial: input.serial,
						local_path: localPath,
						device_path: devicePath,
						bytes: digest.bytes,
						sha256: digest.sha256,
						device_sha256: deviceDigest.device_sha256,
						overwritten: deviceExists,
						device_digest_source: deviceDigest.device_digest_source
